# بدون تحسين: استعلام إضافي لكل post.author
for post in Post.objects.all():
    print(post.author.username)  # N+1 queries

# مع select_related: استعلام واحد فقط بـ JOIN
for post in Post.objects.select_related("author"):
    print(post.author.username)  # استعلام واحد فقط

# بدون تحسين: استعلام منفصل لكل post.comments.all()
for post in Post.objects.all():
    print(post.comments.count())  # N+1 queries

# مع prefetch_related: استعلامان فقط بالمجمل
for post in Post.objects.prefetch_related("comments"):
    print(post.comments.count())

from django.db.models import Avg, Sum

result = Post.objects.aggregate(
    total_views=Sum("views"),
    avg_views=Avg("views"),
)
print(result)  # {'total_views': 1520, 'avg_views': 76.0}

latest_post = Post.objects.order_by("-created_at").first()
if latest_post:
    print(latest_post.title)
else:
